SELECT device_code, DATE_TRUNC('DAY', reading_ts) AS activity_day, STDDEV_SAMP(temp_c) AS temp_c_stddev, CORR(status_bits, humidity) AS corr_status_bits_humidity, STDDEV_SAMP(status_bits) AS status_bits_stddev, GROUPING(device_code) AS gid FROM device_readings GROUP BY GROUPING SETS ((device_code, DATE_TRUNC('DAY', reading_ts)), (device_code)) HAVING temp_c_stddev > 0 ORDER BY device_code ASC;
